#!/usr/bin/env python3
import csv
import datetime
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP

FACTORS = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45392"),
    "oz": Decimal("0.02837"),
}
ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
DELIMS = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "river": "MM/DD/YYYY",
             "west": "DD.MM.YYYY", "harbor": "iso"}
COLUMN_ALIASES = {
    "id": "id", "ref": "id",
    "type": "type", "typ": "type", "kind": "type", "t": "type", "rec": "type",
    "shipped": "shipped", "date": "shipped", "shipped_at": "shipped",
    "gross": "weight", "weight": "weight", "gross_kg": "weight",
    "status": "status", "state": "status",
}
KNOWN_COLUMNS = set(COLUMN_ALIASES) | {"net", "net_kg", "note", "booked"}
HARBOR_STATES = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}
FIXED_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}
ID_RE = re.compile(r"^\s*SH\D*0*(\d+)\s*$", re.I)


def decode(path):
    with open(path, "rb") as handle:
        data = handle.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be")
    head = data[:1000].decode("latin-1")
    match = re.search(r"^#\s*charset\s*:\s*([^\s]+)", head, re.I | re.M)
    if match:
        try:
            return data.decode(match.group(1))
        except LookupError:
            pass
    return data.decode("utf-8")


def parse_id(text):
    match = ID_RE.match(text or "")
    return int(match.group(1)) if match else None


def norm_status(text):
    return re.sub(r"[\s\-]+", "_", (text or "").strip().lower())


def rtype(text):
    low = (text or "").strip().lower()
    if low.startswith("v"):
        return "void"
    if low.startswith("c") or low.startswith("a"):
        return "correction"
    return "new"


def parse_date(text, form):
    text = text.strip()
    match = re.match(r"^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$", text)
    if match:
        return datetime.date(int(match.group(3)), MONTHS[match.group(2).lower()],
                             int(match.group(1)))
    match = re.match(r"^(\d{4})-(\d{1,2})-(\d{1,2})", text)
    if match:
        return datetime.date(*map(int, match.groups()))
    if re.match(r"^\d{8}$", text):
        return datetime.date(int(text[:4]), int(text[4:6]), int(text[6:]))
    match = re.match(r"^(\d{1,2})\.(\d{1,2})\.(\d{4})$", text)
    if match:
        return datetime.date(int(match.group(3)), int(match.group(2)), int(match.group(1)))
    form = (form or "").strip()
    upper = form.upper()
    if upper == "SERIAL" or re.match(r"^\d+(\.\d+)?$", text):
        return datetime.date(1899, 12, 31) + datetime.timedelta(days=int(float(text)))
    match = re.match(r"^(\d{1,4})[-/.](\d{1,2})[-/.](\d{1,4})$", text)
    if not match:
        raise ValueError(text)
    first, second, third = (int(g) for g in match.groups())
    if upper in ("ISO", "YMD", "YYYY-MM-DD"):
        return datetime.date(first, second, third)
    if upper in ("DMY", "DD-MM-YYYY", "DD/MM/YYYY", "DD.MM.YYYY"):
        return datetime.date(third, second, first)
    if upper in ("MM/DD/YYYY", "MDY"):
        return datetime.date(third, first, second)
    raise ValueError(text)


def parse_timestamp(text):
    text = text.strip()
    if re.match(r"^\d{4}-\d{2}-\d{2}[T ]", text):
        value = datetime.datetime.fromisoformat(text.replace("Z", "+00:00").replace("z", "+00:00"))
        if value.tzinfo is not None:
            value = value.astimezone(datetime.timezone.utc)
        return value.date()
    return parse_date(text, "iso")


def parse_number(text, depot):
    text = text.strip()
    if depot == "west":
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    return Decimal(text)


def weight_kg(text, depot, unit):
    text = text.strip()
    match = re.match(r"^([-+0-9.,]+)\s*(kg|g|lb|oz)$", text, re.I)
    if match:
        text, unit = match.group(1), match.group(2).lower()
    return parse_number(text, depot) * FACTORS[unit]


def make(num, kind, shipped=None, kg=None, status=None):
    return {"num": num, "type": kind, "date": shipped, "kg": kg, "status": status}


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    quoted = delim == ","
    seq = None
    directives = {}
    header = None
    records = []
    pending = None
    rows = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if pending is not None:
            pending += "\n" + line
            if pending.count('"') % 2 == 0:
                rows.append(pending)
                pending = None
            continue
        if line.startswith("#"):
            rows.append(line)
            continue
        if not line.strip():
            continue
        if quoted and line.count('"') % 2 == 1:
            pending = line
            continue
        rows.append(line)
    if pending is not None:
        rows.append(pending)
    for row in rows:
        if row.startswith("#"):
            match = re.match(r"^#\s*([^:=]+?)\s*[:=]\s*(.*?)\s*$", row)
            if match:
                name = match.group(1).strip().lower()
                directives[name] = match.group(2)
                if name == "seq" and seq is None:
                    digits = re.search(r"\d+", match.group(2))
                    seq = int(digits.group()) if digits else None
            else:
                match = re.search(r"seq\s*=\s*(\d+)", row)
                if match and seq is None:
                    seq = int(match.group(1))
            continue
        fields = next(csv.reader([row], delimiter=delim)) if quoted else row.split(delim)
        names = [field.strip().lower() for field in fields]
        if names and all(name in KNOWN_COLUMNS for name in names) and "status" in names + ["state"][:0] or (
                names and all(name in KNOWN_COLUMNS for name in names) and "state" in names):
            header = names
            continue
        if header is None:
            continue
        unit_value = None
        if len(fields) == len(header) + 1:
            weight_index = next((i for i, name in enumerate(header)
                                 if COLUMN_ALIASES.get(name) == "weight"), None)
            index = None
            if weight_index is not None and fields[weight_index + 1].strip().lower() in FACTORS:
                index = weight_index + 1
            else:
                for i, field in enumerate(fields):
                    if field.strip().lower() in FACTORS:
                        index = i
                        break
            if index is not None:
                unit_value = fields[index].strip().lower()
                fields = fields[:index] + fields[index + 1:]
        if len(fields) != len(header):
            continue
        values = {}
        unit = None
        for name, value in zip(header, fields):
            key = COLUMN_ALIASES.get(name)
            if key:
                values[key] = value
            if key == "weight":
                suffix = re.search(r"_(kg|g|lb|oz)$", name)
                if suffix:
                    unit = suffix.group(1)
        num = parse_id(values.get("id", ""))
        if num is None:
            continue
        kind = rtype(values.get("type", ""))
        if kind == "void":
            records.append(make(num, kind))
            continue
        if unit is None:
            unit = unit_value
        if unit is None:
            unit = (directives.get("weight unit") or directives.get("unit") or "kg").split()[0].lower()
        form = directives.get("dates") or directives.get("date format") or directives.get("date") \
            or BASE_DATE[depot]
        status = norm_status(values.get("status", ""))
        status = HARBOR_STATES.get(values.get("status", "").strip().upper(), status)
        records.append(make(num, kind, parse_date(values["shipped"], form),
                            weight_kg(values["weight"], depot, unit), status))
    return seq, records


LAYOUTS = {
    "FW1": (42, {"id": (0, 9), "type": (9, 10), "shipped": (10, 17), "weight": (17, 25),
                 "status": (25, 26)}),
    "FW2": (43, {"type": (0, 1), "id": (1, 10), "shipped": (10, 18), "weight": (18, 26),
                 "status": (26, 27)}),
    "FW3": (41, {"id": (0, 9), "shipped": (9, 16), "type": (16, 17), "weight": (17, 24),
                 "status": (24, 25)}),
}


def parse_fixed(text):
    seq = None
    layout = None
    records = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\x0c" in line or not line.strip():
            continue
        if line.startswith("#"):
            match = re.match(r"^#LAYOUT\s+(\S+)", line)
            if match:
                layout = match.group(1).upper()
            match = re.match(r"^#SEQ\s+(\d+)", line)
            if match and seq is None:
                seq = int(match.group(1))
            continue
        by_length = [name for name, (length, _) in LAYOUTS.items() if length == len(line)]
        name = by_length[0] if by_length else layout
        if name not in LAYOUTS:
            continue
        cols = LAYOUTS[name][1]
        field = {key: line[a:b] for key, (a, b) in cols.items()}
        num = parse_id(field["id"])
        if num is None:
            continue
        kind = rtype(field["type"])
        if kind == "void":
            records.append(make(num, kind))
            continue
        digits = int(field["weight"])
        shipped = field["shipped"]
        if name == "FW1" or name == "FW3":
            date = datetime.date(int(shipped[:4]), 1, 1) + datetime.timedelta(days=int(shipped[4:]) - 1)
        else:
            date = datetime.date(int(shipped[:4]), int(shipped[4:6]), int(shipped[6:8]))
        if name == "FW1":
            kg = Decimal(digits) * FACTORS["g"]
        elif name == "FW2":
            kg = Decimal(digits) / 100
        else:
            kg = Decimal(digits) / 10 * FACTORS["lb"]
        records.append(make(num, kind, date, kg, FIXED_STATUS.get(field["status"].strip().upper(), "")))
    return seq, records


def local(tag):
    return tag.rsplit("}", 1)[-1]


def parse_xml(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text)
    root = ET.fromstring(text)
    seq = None
    if root.get("seq") is not None:
        seq = int(re.search(r"\d+", root.get("seq")).group())
    root_unit = (root.get("weight-unit") or root.get("unit") or "kg").lower()
    records = []
    for shipment in root.iter():
        if local(shipment.tag) != "shipment":
            continue
        children = {local(child.tag): child for child in shipment}
        num = parse_id(shipment.get("id") or (children["id"].text if "id" in children else ""))
        if num is None:
            continue
        kind = rtype(shipment.get("type", ""))
        if kind == "void":
            records.append(make(num, kind))
            continue
        if "shipped" in children:
            shipped_text = children["shipped"].text or ""
        else:
            shipped_text = shipment.get("shipped", "")
        weight = children.get("weight")
        unit = (weight.get("unit") if weight is not None else None) \
            or shipment.get("weight-unit") or shipment.get("unit") or root_unit
        records.append(make(
            num, kind, parse_timestamp(shipped_text),
            weight_kg((weight.text or "") if weight is not None else "0", "xml", unit.lower()),
            norm_status(children["status"].text if "status" in children else shipment.get("status"))))
    return seq, records


def parse_json(text):
    seq = None
    records = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        value = json.loads(line)
        items = value if isinstance(value, list) else [value]
        for item in items:
            if not isinstance(item, dict):
                continue
            if "meta" in item and "id" not in item:
                meta = item["meta"]
                if seq is None and isinstance(meta, dict) and meta.get("seq") is not None:
                    seq = int(meta["seq"])
                continue
            num = parse_id(str(item.get("id", "")))
            if num is None:
                continue
            kind = rtype(item.get("kind", ""))
            if kind == "void":
                records.append(make(num, kind))
                continue
            kg = None
            for key, raw in item.items():
                match = re.match(r"^weight_(kg|g|lb|oz)$", key)
                if match:
                    kg = Decimal(str(raw)) * FACTORS[match.group(1)]
            records.append(make(num, kind, parse_timestamp(item["shipped_at"]), kg,
                                norm_status(item.get("status"))))
    return seq, records


def parse_file(depot, path):
    text = decode(path)
    if text.startswith("\ufeff"):
        text = text[1:]
    if depot == "central":
        return parse_xml(text)
    if depot == "north":
        return parse_json(text)
    if depot == "south":
        return parse_fixed(text)
    if depot in DELIMS:
        return parse_delimited(depot, text)
    stripped = text.lstrip()
    if stripped.startswith("<"):
        return parse_xml(text)
    if stripped.startswith("{") or stripped.startswith("["):
        return parse_json(text)
    return parse_fixed(text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = parse_file(depot, path)
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = 0
    resends = 0
    current = {}
    for depot, files in exports.items():
        state = {}
        for _, _, records in sorted(files, key=lambda item: (item[0], item[1])):
            for record in records:
                num = record["num"]
                if record["type"] == "new":
                    if num in state:
                        resends += 1
                    else:
                        state[num] = record
                elif record["type"] == "correction":
                    state[num] = record
                    corrections += 1
                else:
                    state.pop(num, None)
                    corrections += 1
        current[depot] = state

    def rank(depot):
        return ORDER.index(depot) if depot in ORDER else len(ORDER)

    owners = {}
    for depot in sorted(current, key=lambda d: (rank(d), d)):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for depots in owners.values() if len(depots) > 1)

    depots = {depot: [0, Decimal(0)] for depot in sorted(exports)}
    months = {}
    for num, depot_list in owners.items():
        depot = depot_list[0]
        record = current[depot][num]
        if record["status"] not in ("delivered", "delivered_late"):
            continue
        depots[depot][0] += 1
        depots[depot][1] += record["kg"]
        key = "%04d-%02d" % (record["date"].year, record["date"].month)
        entry = months.setdefault(key, [0, Decimal(0)])
        entry[0] += 1
        entry[1] += record["kg"]

    def pack(entry):
